const items = $input.all();

const result = {};

for (const key of Object.keys(items[0].json)) {

  if (key === 'ID Producto') {
    result['Productos'] = items.length;
    continue;
  }

  const values = items
    .map(item => item.json[key])
    .filter(value => typeof value === 'number');

  if (values.length > 0) {

    const promedio =
      values.reduce((a, b) => a + b, 0) / values.length;

    result[key] =
      key === 'Promedio diferencia pagos'
        ? Math.round(promedio * 100) / 100 // 2 decimales
        : Math.round(promedio * 10) / 10;  // 1 decimal
  }
}

return [{ json: result }];

