const from = $json.From || '';

const email = from.match(/<([^>]+)>/)?.[1] || '';

const nombre = (from.match(/^(.*?)\s*<[^>]+>/)?.[1] || from)
  .replace(/^["']+|["']+$/g, '')
  .trim();

return [{
json: {
Subject: $json.Subject,
Snippet: $json.snippet,
Nombre: nombre,
Email: email
}
}];

const texto = $json.text;

// Busca cada persona
const regexPersona = /([A-Za-zÁÉÍÓÚáéíóúÑñ\s]+),\s*DNI\s*([\d.]+),\s*correo electrónico\s*([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})/g;

const coincidencias = [...texto.matchAll(regexPersona)];

const resultados = [];

for (let i = 0; i < coincidencias.length; i++) {

  const actual = coincidencias[i];

  const inicio = actual.index;

  const fin = i < coincidencias.length - 1
    ? coincidencias[i + 1].index
    : texto.length;

  const bloque = texto.slice(inicio, fin);

  const extraer = (desde, hasta) => {
    if (hasta === "$") {
      const re = new RegExp(`${desde}\\s*([\\s\\S]*)`, "i");
      const m = bloque.match(re);

      return m
        ? m[1].replace(/\s+/g, " ").trim()
        : "";
    }

    const re = new RegExp(
      `${desde}\\s*([\\s\\S]*?)\\s*${hasta}`,
      "i"
    );

    const m = bloque.match(re);

    return m
      ? m[1].replace(/\s+/g, " ").trim()
      : "";
  };

  resultados.push({
    Fecha: new Date().toISOString().slice(0,10).replace(/-/g, ''),
    Nombre: actual[1]
      .replace(/Datos Personales/g, "")
      .trim()
      .split("\n")
      .pop()
      .trim(),

    DNI: Number(actual[2].replace(/\./g, '')),

    Email: actual[3].trim(),

    "Situacion laboral": extraer(
      "Situación Laboral e Ingresos",
      "Patrimonio"
    ),

    Patrimonio: extraer(
      "Patrimonio",
      "Pasivos o Deudas"
    ),

    "Pasivos y deudas": extraer(
      "Pasivos o Deudas",
      "Historial Crediticio"
    ),

    "Historial crediticio": extraer(
      "Historial Crediticio",
      "Flujo de Caja Personal"
    ),

    "Flujo de caja": extraer(
      "Flujo de Caja Personal",
      "Indicadores Financieros"
    ),

    "Indicadores financieros": extraer(
      "Indicadores Financieros",
      "Conclusión"
    ),

    Conclusion: extraer(
      "Conclusión",
      "$"
    )
  });
}

return resultados.map(item => ({
  json: item
}));

